import fs from 'node:fs';
const path = process.argv[2];
const MAX = Number(process.argv[3] || 700);
const lines = fs.readFileSync(path, 'utf8').split('\n').filter(Boolean);
const clip = (s, n = MAX) => {
  s = String(s ?? '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + ` …[+${s.length - n}ch]` : s;
};
let prev = null;
for (const line of lines) {
  let e;
  try { e = JSON.parse(line); } catch { console.log('UNPARSEABLE: ' + clip(line, 200)); continue; }
  const ts = e.timestamp || e.ts || '';
  const t = ts ? new Date(ts).getTime() : null;
  const gap = t && prev ? ((t - prev) / 1000).toFixed(1) + 's' : '';
  if (t) prev = t;
  const type = e.type || e.role || '?';
  const msg = e.message || e;
  const role = msg.role || type;
  const usage = msg.usage ? `[in ${msg.usage.input_tokens ?? 0}+${msg.usage.cache_read_input_tokens ?? 0}c out ${msg.usage.output_tokens ?? 0}]` : '';
  const head = `\n--- ${ts} (+${gap}) ${type}/${role} ${usage}`;
  const content = msg.content;
  if (typeof content === 'string') { console.log(head); console.log('  TEXT: ' + clip(content)); continue; }
  if (!Array.isArray(content)) { console.log(head); console.log('  RAW: ' + clip(JSON.stringify(e))); continue; }
  console.log(head);
  for (const b of content) {
    if (b.type === 'text') console.log('  TEXT: ' + clip(b.text));
    else if (b.type === 'thinking') console.log('  THINK: ' + clip(b.thinking, 400));
    else if (b.type === 'tool_use') console.log(`  TOOL_USE ${b.name}: ` + clip(JSON.stringify(b.input), 500));
    else if (b.type === 'tool_result') console.log(`  TOOL_RESULT${b.is_error ? ' ERROR' : ''}: ` + clip(typeof b.content === 'string' ? b.content : JSON.stringify(b.content), b.is_error ? 700 : 350));
    else console.log(`  ${b.type}: ` + clip(JSON.stringify(b), 200));
  }
}

